def cashflows(c, n, m=2):                 # 面值 100，半年付息
    return [(t, (c / m) * 100.0 + (100.0 if t == n * m else 0.0))
            for t in range(1, n * m + 1)]

def price(c, y, n, m=2):
    return sum(cf / (1 + y / m / 100.0)  t for t, cf in cashflows(c, n, m))

def mod_dur(c, y, n, m=2):                # 修正久期 = 麦考利久期 / (1 + y/m)
    pv = price(c, y, n, m)
    mac = sum((t / m) * cf / (1 + y / m / 100.0)  t
              for t, cf in cashflows(c, n, m)) / pv
    return mac / (1 + y / m / 100.0)

print(mod_dur(5.29, 5.29, 10))                 # 7.688
print(round(-7.688 * 1.71, 2))                 # -13.15   一阶
print(round(price(5.29, 7.00, 10) - 100, 2))   # -12.15   重价
